package io.github.phiscript.capture;import android.content.Context;import android.view.WindowManager;public class RecognitionOverlay {private Context context;private WindowManager manager;public int hides;public RecognitionOverlay(Context c){context=c;manager=(WindowManager)c.manager;}public long hide(){hides++;return 0;}public Context host(){return context;}public WindowManager wm(){return manager;}}
